# The hand reached its staging pose; the reference will leave the right end of the belt.
# I will shift above the central lane and wait for the next objects with fingers clear.
obs, used, reason = servo_ee('right', [0.20,0.0,1.10,0.5,-0.5,0.5,0.5], 1.0, 16)
print('stage', used, reason, obs['state']['right_ee_pose'])
fixed_action = {k: v for k, v in obs['state'].items() if k.endswith('joint_state')}
for i in range(65):
    obs, reward, terminated, truncated, info = step(fixed_action)
    if terminated or truncated:
        break
print('wait', i+1, info)

